#include "shell/screen_registry.hpp"
#include "support/check.hpp"
#include <stdexcept>
struct Bridge: squiflow::shell::PresentationBridge{};
int main(){namespace t=squiflow::testing;using namespace squiflow;using namespace squiflow::shell;ScreenRegistry r;int made=0;r.add({protocol::ModuleId::administration,"orders.list","orders.title","orders","qrc:/Orders.qml","work",7,[&]{++made;return std::make_unique<Bridge>();}});bool active=true,allowed=false;ScreenAccess access{[&](auto){return active;},[&](auto){return allowed;}};t::check(r.visible(access).empty(),"unauthorized screen hidden");t::check(!r.create("orders.list",access)&&made==0,"unauthorized bridge never constructed");allowed=true;t::check(r.visible(access).size()==1,"authorized screen visible");auto bridge=r.create("orders.list",access);t::check(bridge&&made==1,"bridge lazily created");active=false;t::check(!r.create("orders.list",access)&&made==1,"inactive bridge never created");try{r.add({protocol::ModuleId::administration,"orders.list","x","x","x","x",0,[]{return std::make_unique<Bridge>();}});t::check(false,"duplicate rejected");}catch(const std::logic_error&){t::check(true,"duplicate rejected");}return t::report();}
